#!/command/with-contenv bash
set -euo pipefail
export MYSQL_PWD=$DB_PASSWORD
sql() { mariadb --skip-ssl -h db -u root "$@"; }
# MySQL uses its autogenerated self-signed certificate; configure the isolated
# fixture client to accept that certificate for this test only.
mkdir -p /root/.my.cnf.d
printf '[client]\nskip-ssl\n' > /root/.my.cnf
# Exercise the same scoped privileges used by application backup deployments.
sql -e "CREATE USER 'backup_user'@'%' IDENTIFIED BY 'test-only'; GRANT SELECT, SHOW VIEW, TRIGGER ON backup_test.* TO 'backup_user'@'%';"
sql -e 'CREATE TABLE backup_test.fixture (id INT PRIMARY KEY, value TEXT); INSERT INTO backup_test.fixture VALUES (1,"backup survives restore");'
mkdir -p "$BACKUP_DIR/daily" "$BACKUP_DIR/monthly"
old=$(date -u -d "@$(($(date +%s) - 8*86400))" +%F)
recent=$(date -u -d "@$(($(date +%s) - 2*86400))" +%F)
month=$(date -u +%Y-%m)
year=$(date -u +%Y)
printf old > "$BACKUP_DIR/daily/$old.sql.gz"
printf recent > "$BACKUP_DIR/daily/$recent.sql.gz"
printf expired > "$BACKUP_DIR/monthly/$((year-2))-01.sql.gz"
printf retained > "$BACKUP_DIR/monthly/$((year-1))-${month:5:2}.sql.gz"
printf unmanaged > "$BACKUP_DIR/daily/keep.txt"
DB_USER=backup_user mysql-backup.sh
test ! -f "$BACKUP_DIR/daily/$old.sql.gz"
test -f "$BACKUP_DIR/daily/$recent.sql.gz"
test ! -f "$BACKUP_DIR/monthly/$((year-2))-01.sql.gz"
test -f "$BACKUP_DIR/monthly/$((year-1))-${month:5:2}.sql.gz"
test -f "$BACKUP_DIR/daily/keep.txt"
file="$BACKUP_DIR/daily/$(date -u +%F).sql.gz"
test "$(stat -c %a "$file")" = 600
cmp "$file" "$BACKUP_DIR/monthly/$month.sql.gz"
before=$(sha256sum "$file")
printf preserve > "$BACKUP_DIR/daily/$old.sql.gz"
if DB_PORT=1 mysql-backup.sh; then echo 'Failed dump returned success' >&2; exit 1; fi
test "$before" = "$(sha256sum "$file")"
test -f "$BACKUP_DIR/daily/$old.sql.gz"
test -z "$(find "$BACKUP_DIR" -name '.partial.*')"
sql -e 'DROP DATABASE backup_test'
gzip -dc "$file" | sql
test "$(sql -N -e 'SELECT value FROM backup_test.fixture WHERE id=1')" = 'backup survives restore'
echo 'Dump, restore, retention and failure checks passed'
